function totalNQueens(n: number): number {
  // Занятые столбцы и диагонали.
  // На «\»-диагонали постоянна разность row - col (сдвигаем на n - 1, чтобы индекс был >= 0),
  // на «/»-диагонали постоянна сумма row + col.
  const cols: boolean[] = new Array(n).fill(false);
  const diag: boolean[] = new Array(2 * n - 1).fill(false);
  const anti: boolean[] = new Array(2 * n - 1).fill(false);
  let count = 0;

  // Ставим ровно одного ферзя в каждую строку, сверху вниз
  const backtrack = (row: number): void => {
    if (row === n) {
      // Все n ферзей расставлены без конфликтов
      count++;
      return;
    }

    for (let col = 0; col < n; col++) {
      const d = row - col + n - 1;
      const a = row + col;
      // Клетка бьётся уже стоящим ферзём — пропускаем
      if (cols[col] || diag[d] || anti[a]) continue;

      // Ставим ферзя
      cols[col] = diag[d] = anti[a] = true;
      backtrack(row + 1);
      // Убираем ферзя (откат)
      cols[col] = diag[d] = anti[a] = false;
    }
  };

  backtrack(0);
  return count;
}

// Время: O(n!) — в строке k остаётся не больше n - k свободных столбцов
// Память: O(n) на массивы занятости и рекурсию
